@spec sample_page_spec  src=tests/specs/sample_page_spec.lua  loc=92  cases=5
@exercises commandManager (h.cmgr)
@surface   cmgr:installManifest, cmgr:scope
@harness   mk

# Intent
  Pin-tests for samplePage's Page interface (bind / unbind / focusState).
  Render methods pull in ImGui and are exercised manually in REAPER.
  
  samplePage requires ImGui at module scope; stub via package.preload
  before the first require so the module loads in the pure-Lua harness.

# Helpers
  @fn newSamplePage(cm, cmgr, chrome, gui)  @ 20-23

# Cases
  @case 'the manifest declares every command the sample page registers'  [harness]  @ 30-45
  @case 'setTrack(track) re-keys cm to that track via the page's own sv'  [harness]  @ 49-57
  @case 'setTrack(nil) does not re-key cm'  [harness]  @ 60-68
  @case 'focusState before any render returns both bits false'  [harness]  @ 71-78
  @case 'bind re-keys cm to the page track on every activation, not just the first'  [harness]  @ 81-90

# Uses (outbound edges)
  @use call cmgr:installManifest  @ 37
  @use call cmgr:scope  @ 39

# Fields (r read / w write incl. constructor keys)
  @field w ImGui_GetBuiltinPath  @ 13
  @field r acceptCmds  @ 77
